using Lastlight.Core;
using System.Text.Json;
public static class InstitutionEdges
{
 public static void Run(Definitions d,string output)
 {
  Directory.CreateDirectory(output);void Require(bool v,string m){if(!v)throw new Exception(m);}void Steps(World w,int n){for(int i=0;i<n;i++)w.Step(d);}void Until(World w,Func<bool> done,int limit){for(int i=0;i<limit&&!done();i++)w.Step(d);Require(done(),"Legacy expedition stalled.");w.Validate(d);}
  var original=InstitutionsWorldGenerator.Create(d,74219);long elder=original.Colony.People.Keys.First(),dead=original.Colony.People.Keys.Skip(1).First();original.Colony.People[elder].Age=79;original.Body(dead)!.Dead=true;original.Body(dead)!.Downed=true;original.Body(dead)!.DeathCause="Earlier injury";original.Find(dead)!.Health=0;original.Validate(d);var next=original.BeginSuccessor(d,2);var reclaimed=next.ReclaimLegacy(d);Require(reclaimed.Body(elder) is {Dead:true}&&reclaimed.Body(elder)!.DeathCause=="Age during retirement"&&reclaimed.Body(dead) is {Dead:true}&&reclaimed.Body(dead)!.DeathCause=="Earlier injury","Retirement resurrected someone or ignored aging.");Require(reclaimed.Physical.Water.Count==0&&reclaimed.Physical.Devices.Values.All(s=>s.Fuel==0&&s.Charge==0),"Retired utilities kept unexplained stored supplies.");Console.WriteLine("PASS H legacy mortality: old deaths remain dead, 80+ conversion has a recorded cause, drained cisterns conserve water mass and stored fuel/charge expires");
  var w=InstitutionsWorldGenerator.Create(d,74219);long keeper=w.Colony.People.Keys.First(),apprentice=w.Colony.People.Keys.Skip(1).First();var host=w.Entities.First(e=>e.DefinitionId=="study");var found=w.Apply(new(CommandKind.InstitutionAction,keeper,"Library",TargetId:host.Id,Text:"found"),d);Require(found.Accepted,found.Message);w.Colony.People[keeper].Schedule=Enumerable.Repeat(ScheduleActivity.Study,24).ToArray();w.Body(keeper)!.Downed=true;Steps(w,60);Require(w.Society.Institutions.Single().Sessions==0,"Incapacitated keeper held sessions.");w.Apply(new(CommandKind.Remove,host.Id),d);w.Validate(d);Require(w.Society.Institutions.Count==0&&w.Society.Apprentices.Count==0,"Removed host retained invalid references.");Console.WriteLine("PASS H institutions: incapacitated keeper cannot teach; removal releases institutional references and jobs");
  var archiveWorld=InstitutionsWorldGenerator.Create(d,74219);var item=archiveWorld.Apply(new(CommandKind.Spawn,DefinitionId:"formula-folio",X:62,Y:67),d);Require(item.Accepted,item.Message);var artifact=new RegionArtifact{Id=archiveWorld.Region.NextId++,Name="Founders' annotated folio",DefinitionId="formula-folio",SiteId=archiveWorld.Region.HomeSiteId,Custody="Colony",LocalEntityId=item.EntityId};archiveWorld.Region.Artifacts.Add(artifact);var successor=archiveWorld.BeginSuccessor(d,3);long leader=successor.Colony.People.Keys.First();successor.Apply(new(CommandKind.Spawn,DefinitionId:"meal",X:62,Y:67,Quantity:8),d);var depart=successor.Apply(new(CommandKind.RegionAction,leader,leader.ToString(),TargetId:successor.Society.Legacy!.SiteId,Text:"depart",Quantity:2),d);Require(depart.Accepted,depart.Message);var party=successor.Region.Parties.Single();Until(successor,()=>party.State=="AtSite",25000);var inherited=successor.Region.Artifacts.Single(a=>a.Id==artifact.Id);var local=successor.Find(inherited.LocalEntityId)!;var move=successor.Apply(new(CommandKind.MoveDrafted,leader,X:local.X-1,Y:local.Y,Z:local.Z),d);Require(move.Accepted,move.Message);Until(successor,()=>Math.Abs(successor.Find(leader)!.X-local.X)+Math.Abs(successor.Find(leader)!.Y-local.Y)<=1,10000);var take=successor.Apply(new(CommandKind.RegionAction,leader,TargetId:artifact.Id,Text:"take"),d);Require(take.Accepted,take.Message);Require(!successor.Apply(new(CommandKind.RegionAction,leader,TargetId:artifact.Id,Text:"take"),d).Accepted,"Inherited artifact recovered twice.");successor.Validate(d);successor.Apply(new(CommandKind.RegionAction,TargetId:party.Id,Text:"return"),d);Until(successor,()=>party.State=="Returned",25000);Require(inherited.Custody=="Colony"&&successor.Find(inherited.LocalEntityId)!.Name==artifact.Name&&successor.Region.Artifacts.Count(a=>a.Id==artifact.Id)==1,"Inherited artifact identity/custody duplicated or lost on return.");SaveStore.Write(Path.Combine(output,"legacy-artifact-returned.lastlight"),successor,new(){CameraX=64,CameraY=64,OpenTab="History"},d);bool blocked=false;try{successor.ReclaimLegacy(d);}catch(InvalidOperationException){blocked=true;}Require(blocked,"Visited site could be reclaimed into duplicate artifacts.");Console.WriteLine("PASS H artifact edge: real successor travel/movement/pickup/return keeps a named inherited folio unique; repeated pickup and post-visit reclaim cannot duplicate it");
  var malformed=archiveWorld.BeginSuccessor(d,3);var nested=JsonSerializer.Deserialize<World>(malformed.Society.Legacy!.Snapshot,JsonFormat.Options)!;nested.Society.Legacy=new(){SiteId=nested.Region.HomeSiteId};malformed.Society.Legacy.Snapshot=JsonSerializer.Serialize(nested,JsonFormat.Options);bool rejected=false;try{malformed.Validate(d);}catch(InvalidDataException){rejected=true;}Require(rejected,"Nested retirement archive accepted.");Console.WriteLine("PASS H archive edge: nested archive rejected before recursive validation");
 }
}
